-- generated by src/lib/testing/db_invariants.gen.sql.ts: the database invariants, $1 the keeper role and $2 the admin role
WITH
	role_param AS (SELECT $1::text AS keeper, $2::text AS admin),
	removal AS (
		SELECT target_account_id AS account_id, event_type, seq, created_at
		FROM audit_log
		WHERE outcome = 'success'
		  AND event_type IN ('account_delete', 'account_purge')
		  AND target_account_id IS NOT NULL
	),
	offer_party AS (
		SELECT o.id, o.from_actor_id, fa.account_id AS from_account_id, o.to_account_id,
			o.to_actor_id, o.created_at,
			(SELECT MIN(al.seq) FROM audit_log al
				WHERE al.event_type = 'role_grant_offer_create' AND al.outcome = 'success'
				  AND al.metadata->>'offer_id' = o.id::text) AS create_seq
		FROM role_grant_offer o
		JOIN actor fa ON fa.id = o.from_actor_id
		WHERE o.accepted_at IS NULL AND o.declined_at IS NULL AND o.retracted_at IS NULL AND o.superseded_at IS NULL
	),
	invite_issuer AS (
		SELECT i.id, i.created_by, i.created_at, a.deleted_at IS NOT NULL AS actor_dead,
			COALESCE(a.account_id, (SELECT al.account_id FROM audit_log al
				WHERE al.event_type = 'invite_create' AND al.outcome = 'success'
				  AND al.metadata->>'invite_id' = i.id::text
				ORDER BY al.seq LIMIT 1)) AS issuer_account_id,
			(SELECT MIN(al.seq) FROM audit_log al
				WHERE al.event_type = 'invite_create' AND al.outcome = 'success'
				  AND al.metadata->>'invite_id' = i.id::text) AS create_seq
		FROM invite i
		LEFT JOIN actor a ON a.id = i.created_by
		WHERE i.claimed_at IS NULL
	),
	token_issued AS (
		SELECT t.id, t.account_id, t.created_at,
			(SELECT MIN(al.seq) FROM audit_log al
				WHERE al.event_type = 'token_create' AND al.outcome = 'success'
				  AND al.metadata->>'token_id' = t.id) AS create_seq
		FROM api_token t
	)
SELECT 'credential_of_tombstoned_account' AS invariant, jsonb_build_object('kind', v.kind, 'id', v.id, 'account_id', v.account_id)::text AS row FROM (SELECT 'auth_session' AS kind, LEFT(s.id, 12) AS id, s.account_id
			FROM auth_session s JOIN account ac ON ac.id = s.account_id
			WHERE ac.deleted_at IS NOT NULL
			UNION ALL
			SELECT 'api_token' AS kind, t.id, t.account_id
			FROM api_token t JOIN account ac ON ac.id = t.account_id
			WHERE ac.deleted_at IS NOT NULL) v
UNION ALL
SELECT 'pending_offer_with_dead_party' AS invariant, jsonb_build_object('id', v.id, 'from_actor_id', v.from_actor_id, 'from_account_id', v.from_account_id, 'to_account_id', v.to_account_id, 'to_actor_id', v.to_actor_id, 'from_actor_dead', v.from_actor_dead, 'from_account_dead', v.from_account_dead, 'to_account_dead', v.to_account_dead, 'to_actor_dead', v.to_actor_dead)::text AS row FROM (SELECT op.id, op.from_actor_id, op.from_account_id, op.to_account_id, op.to_actor_id,
				fa.deleted_at IS NOT NULL AS from_actor_dead,
				fac.deleted_at IS NOT NULL AS from_account_dead,
				ta.deleted_at IS NOT NULL AS to_account_dead,
				COALESCE(tac.deleted_at IS NOT NULL, false) AS to_actor_dead
			FROM offer_party op
			JOIN actor fa ON fa.id = op.from_actor_id
			JOIN account fac ON fac.id = op.from_account_id
			JOIN account ta ON ta.id = op.to_account_id
			LEFT JOIN actor tac ON tac.id = op.to_actor_id
			WHERE fa.deleted_at IS NOT NULL OR fac.deleted_at IS NOT NULL
			   OR ta.deleted_at IS NOT NULL OR tac.deleted_at IS NOT NULL) v
UNION ALL
SELECT 'unclaimed_invite_of_dead_issuer' AS invariant, jsonb_build_object('id', v.id, 'created_by', v.created_by, 'issuer_account_id', v.issuer_account_id, 'actor_dead', v.actor_dead, 'issuer_purged', v.issuer_purged)::text AS row FROM (SELECT ii.id, ii.created_by, ii.issuer_account_id,
				ii.actor_dead, ac.id IS NULL AS issuer_purged
			FROM invite_issuer ii
			LEFT JOIN account ac ON ac.id = ii.issuer_account_id
			WHERE ii.issuer_account_id IS NOT NULL
			  AND (ii.actor_dead OR ac.id IS NULL OR ac.deleted_at IS NOT NULL)) v
UNION ALL
SELECT 'bootstrapped_without_live_keeper' AS invariant, jsonb_build_object('bootstrapped', v.bootstrapped)::text AS row FROM (SELECT true AS bootstrapped FROM bootstrap_lock
			WHERE bootstrapped AND NOT EXISTS (
		SELECT 1 FROM role_grant rg
		JOIN actor a ON a.id = rg.actor_id
		JOIN account ac ON ac.id = a.account_id
		WHERE rg.role = (SELECT keeper FROM role_param)
		  AND rg.scope_id IS NULL
		  AND rg.revoked_at IS NULL AND (rg.expires_at IS NULL OR rg.expires_at > NOW())
		  AND a.deleted_at IS NULL
		  AND ac.deleted_at IS NULL
	)) v
UNION ALL
SELECT 'bootstrapped_without_live_admin' AS invariant, jsonb_build_object('bootstrapped', v.bootstrapped)::text AS row FROM (SELECT true AS bootstrapped FROM bootstrap_lock
			WHERE bootstrapped AND NOT EXISTS (
		SELECT 1 FROM role_grant rg
		JOIN actor a ON a.id = rg.actor_id
		JOIN account ac ON ac.id = a.account_id
		WHERE rg.role = (SELECT admin FROM role_param)
		  AND rg.scope_id IS NULL
		  AND rg.revoked_at IS NULL AND (rg.expires_at IS NULL OR rg.expires_at > NOW())
		  AND a.deleted_at IS NULL
		  AND ac.deleted_at IS NULL
	)) v
UNION ALL
SELECT 'account_without_bootstrap' AS invariant, jsonb_build_object('account_id', v.account_id)::text AS row FROM (SELECT ac.id AS account_id FROM account ac
			WHERE NOT EXISTS (SELECT 1 FROM bootstrap_lock WHERE bootstrapped)) v
UNION ALL
SELECT 'actor_tombstone_disagrees_with_account' AS invariant, jsonb_build_object('actor_id', v.actor_id, 'account_id', v.account_id, 'actor_dead', v.actor_dead, 'account_dead', v.account_dead)::text AS row FROM (SELECT a.id AS actor_id, a.account_id,
				a.deleted_at IS NOT NULL AS actor_dead, ac.deleted_at IS NOT NULL AS account_dead
			FROM actor a JOIN account ac ON ac.id = a.account_id
			WHERE (a.deleted_at IS NULL) <> (ac.deleted_at IS NULL)) v
UNION ALL
SELECT 'offer_to_actor_outside_to_account' AS invariant, jsonb_build_object('id', v.id, 'to_account_id', v.to_account_id, 'to_actor_id', v.to_actor_id, 'to_actor_account_id', v.to_actor_account_id)::text AS row FROM (SELECT o.id, o.to_account_id, o.to_actor_id, a.account_id AS to_actor_account_id
			FROM role_grant_offer o JOIN actor a ON a.id = o.to_actor_id
			WHERE a.account_id <> o.to_account_id) v
UNION ALL
SELECT 'invite_claimed_by_without_claimed_at' AS invariant, jsonb_build_object('id', v.id, 'claimed_by', v.claimed_by)::text AS row FROM (SELECT i.id, i.claimed_by FROM invite i
			WHERE i.claimed_by IS NOT NULL AND i.claimed_at IS NULL) v
UNION ALL
SELECT 'pending_offer_outlived_party_removal' AS invariant, jsonb_build_object('id', v.id, 'from_actor_id', v.from_actor_id, 'from_account_id', v.from_account_id, 'to_account_id', v.to_account_id)::text AS row FROM (SELECT op.id, op.from_actor_id, op.from_account_id, op.to_account_id
			FROM offer_party op
			WHERE EXISTS (
		SELECT 1 FROM removal r
		WHERE r.account_id = op.from_account_id
		  AND r.event_type IN ('account_delete')
		  AND CASE WHEN op.create_seq IS NULL THEN r.created_at >= op.created_at
						ELSE r.seq > op.create_seq END
	)
			   OR EXISTS (
		SELECT 1 FROM removal r
		WHERE r.account_id = op.to_account_id
		  AND r.event_type IN ('account_delete')
		  AND CASE WHEN op.create_seq IS NULL THEN r.created_at >= op.created_at
						ELSE r.seq > op.create_seq END
	)) v
UNION ALL
SELECT 'unclaimed_invite_outlived_issuer_removal' AS invariant, jsonb_build_object('id', v.id, 'created_by', v.created_by, 'issuer_account_id', v.issuer_account_id)::text AS row FROM (SELECT ii.id, ii.created_by, ii.issuer_account_id
			FROM invite_issuer ii
			WHERE EXISTS (
		SELECT 1 FROM removal r
		WHERE r.account_id = ii.issuer_account_id
		  AND r.event_type IN ('account_delete', 'account_purge')
		  AND CASE WHEN ii.create_seq IS NULL THEN r.created_at >= ii.created_at
						ELSE r.seq > ii.create_seq END
	)) v
UNION ALL
SELECT 'credential_outlived_account_removal' AS invariant, jsonb_build_object('kind', v.kind, 'id', v.id, 'account_id', v.account_id)::text AS row FROM (SELECT 'auth_session' AS kind, LEFT(s.id, 12) AS id, s.account_id
			FROM auth_session s
			WHERE EXISTS (
		SELECT 1 FROM removal r
		WHERE r.account_id = s.account_id
		  AND r.event_type IN ('account_delete')
		  AND r.created_at >= s.created_at
	)
			UNION ALL
			SELECT 'api_token' AS kind, ti.id, ti.account_id
			FROM token_issued ti
			WHERE EXISTS (
		SELECT 1 FROM removal r
		WHERE r.account_id = ti.account_id
		  AND r.event_type IN ('account_delete')
		  AND CASE WHEN ti.create_seq IS NULL THEN r.created_at >= ti.created_at
						ELSE r.seq > ti.create_seq END
	)) v
